def ls(a, b):
    import numpy as n
    return n.linalg.lstsq(a, b, rcond=None)[0]

def poly(x, d):
    from itertools import combinations_with_replacement
    import numpy as n
    return n.column_stack([n.ones(len(x))] + [n.prod(x[:, j], axis=1) for k in range(1, d + 1) for j in combinations_with_replacement(range(x.shape[1]), k)])

def mat(x, d):
    from itertools import combinations_with_replacement
    import numpy as n
    return n.column_stack([n.ones(len(x))] + [n.prod(x[:, j], axis=1) for k in range(1, d + 1) for j in combinations_with_replacement(range(4), k)])

def fit(x, y):
    import numpy as n
    return n.linalg.lstsq(x, y, rcond=None)[0]

def features(W, typ):
    from itertools import combinations
    import numpy as n
    if typ == 'lin':
        return reg(n.c_[tuple(W)], 0)
    if typ == 'diag':
        return reg(n.c_[tuple(W + [w * w for w in W])], 0)
    if typ == 'cross':
        return reg(n.c_[tuple(W + [W[i] * W[j] for (i, j) in combinations(range(len(W)), 2)])], 0)
    if typ == 'full':
        return reg(n.c_[tuple([poly(w, 2)[:, 1:] for w in W])], 0)
    if typ == 'cube':
        return reg(n.c_[tuple([poly(w, 2)[:, 1:] for w in W] + [w ** 3 for w in W])], 0)

def opfit(u, v, fn, linear):
    from scipy.optimize import least_squares
    import numpy as n

    def des(q, w):
        h = fn(w * n.exp(q))
        return n.c_[n.ones(len(w)), w, h] if linear else n.c_[n.ones(len(w)), h]

    def obj(q):
        D = des(q, u)
        return (D @ ls(D, v) - v).ravel()
    opts = [least_squares(obj, n.full(4, n.log(a)), bounds=(-2, 2), max_nfev=100) for a in [0.65, 1.4, 2.5, 3.8]]
    o = min(opts, key=lambda o: n.linalg.norm(o.fun))
    D = des(o.x, u)
    c = ls(D, v)
    hat = n.sum(D * n.linalg.pinv(D).T, 1)
    err = n.sqrt(n.mean((o.fun.reshape(v.shape) / (1 - hat[:, None])) ** 2))
    return (err, lambda w: des(o.x, w) @ c, n.exp(o.x), c)
